import { defineChapterTopic, type ChapterAuthorSpec } from '../chapter-package-engine';
import type { EducationTopic } from '../education-types';
import type { VERIFIED_SOURCES } from '../verified-sources';

const CLIN_DISCLAIMER =
  'Educational clinical integration overview ONLY. Does NOT substitute for accredited clinical clerkships, supervised bedside care, institutional clinical practice guidelines, or clinical decision-support tools.';

const CLIN_ASSET = {
  status: 'partial' as const,
  summary:
    'System-integrated clinical reasoning cases connecting anatomy, physiology, pathology, and pharmacology—plus 10 Anatomy 360 clinical correlation cases and 3 guided 3D mechanism presentations—are live. Supervised bedside clerkships and real clinical charts remain outside software-only scope.',
};

interface IntegratedCaseTuple {
  anatomy: string;
  physiology: string;
  pathology: string;
  pharmacology: string;
  differentialAnchor: string;
}

function makeClinicalChapter(
  num: number,
  id: string,
  chapterTitle: string,
  title: string,
  summary: string,
  integrated: IntegratedCaseTuple,
  extraReadKey: keyof typeof VERIFIED_SOURCES,
  comp: { colA: string; colB: string; rows: ChapterAuthorSpec['comparisonTable']['rows'] },
  fmas: string[],
  sys: ChapterAuthorSpec['relatedSystems'],
  mcqs: ChapterAuthorSpec['selfChecks'],
): ChapterAuthorSpec {
  const mechanisms = [
    `Anatomical Substrate: ${integrated.anatomy}`,
    `Physiological Derangement: ${integrated.physiology}`,
    `Pathological Mechanism: ${integrated.pathology}`,
    `Pharmacological Target Rationale: ${integrated.pharmacology}`,
  ];
  return {
    id,
    domainId: 'clinical_specialties',
    chapterCode: `O${num}`,
    chapterOrder: num,
    chapterTitle,
    title,
    summary,
    targetTracks: ['medical_foundations', 'clinical_applied'],
    curriculumMappings: [
      { frameworkId: 'pk_pmdc_mbbs', gradeOrYear: 'MBBS Years 3–5', unitOrModule: `Medicine & Surgery Integrated Clerkships (${chapterTitle})`, status: 'compulsory' },
      { frameworkId: 'pk_uhs_mbbs', gradeOrYear: 'MBBS Years 3–5', unitOrModule: `Clinical Rotations (${chapterTitle})`, status: 'institution_specific' },
      { frameworkId: 'hms_pathways', gradeOrYear: 'MD Principal Clinical Experience', unitOrModule: `Clerkship Foundations (${chapterTitle})`, status: 'institution_specific' },
    ],
    prerequisites: ['Gross & regional anatomy (Domain A)', 'Organ physiology (Domain E)', 'Pathology (Domain J) & Pharmacology (Domain K)'],
    learningObjectives: [
      `Integrate regional anatomy, physiological feedback, pathology, and pharmacology mechanisms across core syndromes in ${chapterTitle.toLowerCase()}.`,
      `Structure a safety-first educational differential diagnosis anchored by red-flag symptoms (${integrated.differentialAnchor}).`,
      `Navigate related Anatomy 360 3D structures and clinical correlation cases while observing strict educational-only boundaries.`,
    ],
    depthExplanations: {
      medical_foundations: `${mechanisms.join(' ')} Educational Differential Anchor: ${integrated.differentialAnchor}.`,
      clinical_applied: `Bedside clinical reasoning in ${chapterTitle.toLowerCase()} synthesizes anatomical localization, physiological reserve, underlying tissue pathology, and targeted drug mechanisms: ${integrated.differentialAnchor}. Always remember that real patient care demands supervised clinical evaluation rather than software heuristics.`,
    },
    keyConcepts: [
      { term: 'Anatomy → Physiology Link', definition: `${integrated.anatomy} — ${integrated.physiology}` },
      { term: 'Pathology → Pharmacology Link', definition: `${integrated.pathology} — ${integrated.pharmacology}` },
      { term: 'Red-Flag Educational Anchor', definition: integrated.differentialAnchor },
    ],
    keyFacts: [
      `Integrated Case Pillars: Anatomy + Physiology + Pathology + Pharmacology for ${chapterTitle}.`,
      '10 interactive Anatomy 360 clinical correlation cases and 3 guided 3D mechanism explainers live in /clinical and /present.',
      'Software educational overview ONLY — never use as a diagnostic calculator or treatment protocol.',
    ],
    mechanisms,
    comparisonTable: { columnA: comp.colA, columnB: comp.colB, rows: comp.rows },
    misconceptions: [
      { misconception: 'Clinical specialties treat organ symptoms in isolation without needing basic science mechanisms.', correction: 'Safe differential diagnosis and rational drug selection fail quickly without anatomical localization, haemodynamic/metabolic physiology, and receptor pharmacology.' },
      { misconception: 'An educational curriculum app can confirm diagnoses or doses for real patients.', correction: 'Educational teaching summaries lack patient-specific vitals, physical examination, labs, allergy profiles, and clinical judgment—strictly non-decision-support.' },
    ],
    clinicalCorrelation: integrated.differentialAnchor,
    summaryParagraph: `${chapterTitle} unifies Anatomy, Physiology, Pathology, and Pharmacology into coherent specialty-level clinical reasoning while maintaining transparent educational-only boundaries.`,
    keyTakeaways: [
      integrated.anatomy,
      integrated.pathology,
      integrated.pharmacology,
    ],
    crossSubjectLinks: [
      { domainId: 'pathology', relation: 'Tissue-level disease mechanisms define organ injury patterns presented on the ward.' },
      { domainId: 'pharmacology', relation: 'Therapeutic classes intervene selectively along physiological and pathological pathways.' },
      { domainId: 'clinical_skills_public_health', relation: 'History taking, focused examination, ethics, and EBM structure every clinical encounter.' },
    ],
    relatedSystems: sys,
    relatedFmaConceptIds: fmas,
    visualFormats: ['clinical_case', '3d_anatomy', 'structured_text'],
    diagram: {
      id: `diag-o${num}`,
      title: `${chapterTitle} — 4-Pillar Basic-to-Clinical Integration Map`,
      kind: 'pathway',
      caption: `${chapterTitle}: connecting 3D anatomy & physiology through pathology to pharmacology rationale.`,
      disclaimer: CLIN_DISCLAIMER,
      nodes: [
        { id: 'n1', label: 'Anatomy & Physiology', sublabel: integrated.anatomy.slice(0, 62), tone: 'teal' },
        { id: 'n2', label: 'Pathological Shift', sublabel: integrated.pathology.slice(0, 62), tone: 'rose' },
        { id: 'n3', label: 'Pharmacology Rationale', sublabel: integrated.pharmacology.slice(0, 62), tone: 'blue' },
      ],
      links: [
        { from: 'n1', to: 'n2', label: integrated.physiology.slice(0, 48) },
        { from: 'n2', to: 'n3', label: integrated.differentialAnchor.slice(0, 48) },
      ],
    },
    assetDisclosure: CLIN_ASSET,
    activity: {
      title: `Four-Pillar Clinical Case Integration (${chapterTitle})`,
      kind: 'case_reasoning',
      prompt: `Map an educational ward vignette in ${chapterTitle} across all four pillars (Anatomy, Physiology, Pathology, Pharmacology) and inspect its linked 3D organs (${fmas.length > 0 ? 'visible in 3D Explorer' : 'systematic review'}).`,
      keyTakeaway: integrated.differentialAnchor,
    },
    readingKeys: ['pmdc_mbbs_2024', 'geeky_medics', extraReadKey],
    shortAnswers: [
      { id: `sa-o${num}-1`, prompt: `Connect anatomical structure and normal physiology to the hallmark disease mechanism in ${chapterTitle}.`, expectedPoints: [integrated.anatomy, integrated.physiology, integrated.pathology], modelAnswer: `Anatomy: ${integrated.anatomy} Physiology: ${integrated.physiology} Pathology: ${integrated.pathology}`, level: 'medical_foundations' },
      { id: `sa-o${num}-2`, prompt: `Contrast ${comp.colA} versus ${comp.colB} clinically and mechanistically.`, expectedPoints: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator}`), modelAnswer: comp.rows.map((r) => `${r.dimension}: ${r.primary} vs ${r.comparator} (${r.clinicalOrFunctionalNote}).`).join(' '), level: 'clinical_applied' },
      { id: `sa-o${num}-3`, prompt: `Explain how pharmacological therapy targets the disease mechanism in ${chapterTitle.toLowerCase()} and identify the red-flag differential anchor.`, expectedPoints: [integrated.pharmacology, integrated.differentialAnchor], modelAnswer: `${integrated.pharmacology} Red-flag anchor: ${integrated.differentialAnchor}`, level: 'clinical_applied' },
    ],
    appliedCase: {
      id: `app-o${num}-1`,
      title: `Integrated 4-Pillar Educational Vignette: ${chapterTitle}`,
      scenario: `Educational teaching exercise integrating four foundational sciences: (1) Anatomy — ${integrated.anatomy} (2) Physiology — ${integrated.physiology} (3) Pathology — ${integrated.pathology} (4) Pharmacology — ${integrated.pharmacology}`,
      questions: ['Which anatomical and physiological baseline explains the cardinal presenting symptom?', 'Which red-flag features demand urgent escalation in a supervised clinical setting?'],
      workedSolution: `Differential & Red-Flag Synthesis: ${integrated.differentialAnchor}. Pharmacological mechanism: ${integrated.pharmacology}`,
      level: 'clinical_applied',
      disclaimer: CLIN_DISCLAIMER,
    },
    selfChecks: mcqs,
    educationalDisclaimer: CLIN_DISCLAIMER,
  };
}

